package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Gap-analysis B17: a conjunctive HAVING guard is duplicate-insensitive only when <em>every</em> conjunct is. The old
 * OR-across-conjuncts rule let {@code HAVING(COUNT(?x) >= 1 && COUNT(?x) > 2)} be declared duplicate-insensitive on the
 * strength of its existence-test half alone, so the compiler could collapse join fan-out duplicates and the
 * multiplicity-dependent {@code > 2} half then saw deflated counts — groups wrongly dropped.
 */
public class LmdbNativeConjunctiveHavingTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String JANINO_FLAG = "rdf4j.lmdb.janinoCodegen.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private String previousJanino;

	@BeforeEach
	public void setUp() {
		previousJanino = System.getProperty(JANINO_FLAG);
		System.setProperty(JANINO_FLAG, "false");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			IRI q = vf.createIRI(EX, "q");
			// group g1: one member whose fan-out through ?y produces bag count 3 (collapse would deflate it to 1)
			IRI x1 = vf.createIRI(EX, "x1");
			conn.add(vf.createIRI(EX, "g1"), p, x1);
			conn.add(x1, q, vf.createLiteral("y1"));
			conn.add(x1, q, vf.createLiteral("y2"));
			conn.add(x1, q, vf.createLiteral("y3"));
			// group g2: one member with a single fan-out row — bag count 1 either way
			IRI x2 = vf.createIRI(EX, "x2");
			conn.add(vf.createIRI(EX, "g2"), p, x2);
			conn.add(x2, q, vf.createLiteral("y4"));
		}
	}

	@AfterEach
	public void tearDown() {
		if (previousJanino == null) {
			System.clearProperty(JANINO_FLAG);
		} else {
			System.setProperty(JANINO_FLAG, previousJanino);
		}
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void conjunctiveHavingKeepsMultiplicityDependentConjunctsExact() {
		String query = "SELECT ?g (COUNT(?x) AS ?c) WHERE { ?g <" + EX + "p> ?x . ?x <" + EX + "q> ?y }"
				+ " GROUP BY ?g HAVING(COUNT(?x) >= 1 && COUNT(?x) > 2) ORDER BY ?g";

		List<String> generic = rows(query, false);
		assertThat(generic)
				.as("interpreted oracle: only g1 survives with its exact bag count of 3")
				.containsExactly("c=\"3\"^^<http://www.w3.org/2001/XMLSchema#integer>|g=http://example.com/g1");
		assertThat(rows(query, true))
				.as("native HAVING must evaluate the multiplicity-dependent conjunct on exact bag counts")
				.isEqualTo(generic);
	}

	/** The pure existence guard alone stays duplicate-insensitive — the optimization is retained where sound. */
	@Test
	public void pureExistenceHavingStaysInParity() {
		String query = "SELECT ?g (COUNT(?x) AS ?c) WHERE { ?g <" + EX + "p> ?x . ?x <" + EX + "q> ?y }"
				+ " GROUP BY ?g HAVING(COUNT(?x) >= 1) ORDER BY ?g";

		List<String> generic = rows(query, false);
		assertThat(rows(query, true))
				.as("native results must match the interpreted engine for a pure existence HAVING")
				.isEqualTo(generic);
	}

	private List<String> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(bs -> bs.getBindingNames()
							.stream()
							.sorted()
							.map(name -> name + "=" + bs.getValue(name))
							.collect(Collectors.joining("|")))
					.collect(Collectors.toList());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}
}
